-- 추천 기록의 유입 경로 (source, 20261026170000 마이그레이션): 같은 시각 · 같은 피부타입의 응답에서 가져온다
update public.survey_reco_events e
set source = (
  select r.source from public.survey_responses r
  where r.survey_id = e.survey_id and r.created_at = e.created_at and r.skin_type = e.skin_type
  limit 1
)
from _seed s
where e.survey_id = s.survey_id;

-- 확인: 응답 150 · 18세 미만 9 · 민감 경향 34
select
  (select count(*) from public.survey_responses r join _seed s on r.survey_id = s.survey_id) as responses,
  (select coalesce(sum(count), 0) from public.survey_minor_counts m join _seed s on m.survey_id = s.survey_id) as under18,
  (select count(*) from public.survey_responses r join _seed s on r.survey_id = s.survey_id where r.is_sensitive) as sensitive,
  (select count(*) from public.survey_reco_events e join _seed s on e.survey_id = s.survey_id) as reco_events;

commit;
